// Extract input from parent workflow/AI agent
const input = $input.first().json;

// Log for debugging
console.log('Sub-workflow received:', JSON.stringify(input, null, 2));

// Validate required fields
const action = input.action || 'default';
const data = input.data || {};

return [{
  json: {
    action,
    data,
    receivedAt: new Date().toISOString()
  }
}];

// SEARCH action handler
// Replace with your actual search logic (database, API, etc.)
const data = $input.first().json.data;
const query = data.query || '';

// Simulated search results
const results = [
  { id: 1, title: 'Result 1', relevance: 0.95 },
  { id: 2, title: 'Result 2', relevance: 0.87 },
  { id: 3, title: 'Result 3', relevance: 0.72 }
].filter(r => r.title.toLowerCase().includes(query.toLowerCase()) || !query);

return [{
  json: {
    action: 'search',
    success: true,
    results,
    count: results.length,
    query
  }
}];

// CREATE action handler
// Replace with your actual create logic
const data = $input.first().json.data;

// Simulated create operation
const newRecord = {
  id: Date.now(),
  ...data,
  createdAt: new Date().toISOString()
};

return [{
  json: {
    action: 'create',
    success: true,
    record: newRecord
  }
}];

// UPDATE action handler
// Replace with your actual update logic
const data = $input.first().json.data;
const id = data.id;

if (!id) {
  return [{
    json: {
      action: 'update',
      success: false,
      error: 'No ID provided for update'
    }
  }];
}

// Simulated update operation
const updatedRecord = {
  id,
  ...data,
  updatedAt: new Date().toISOString()
};

return [{
  json: {
    action: 'update',
    success: true,
    record: updatedRecord
  }
}];

// Default/fallback handler
const input = $input.first().json;

return [{
  json: {
    action: input.action || 'unknown',
    success: false,
    error: `Unknown action: ${input.action}`,
    supportedActions: ['search', 'create', 'update']
  }
}];
